insert into public.task_templates (id, idea_no, kind, title, instructions, public_content, duration_sec, scoring, attempts_limit, submission_policy, settings, status, is_placeholder) values
('demo-sprint', 9, 'sprint', 'המרוץ נגד השעון', 'חמש שאלות, אחת אחרי השנייה. תשובה שנשלחה ננעלת, ואין חזרה אחורה.', '{"questions":[{"text":"מי היה המלך הסלווקי שגזר את הגזירות על היהודים?","options":["אלכסנדר מוקדון","אנטיוכוס הרביעי","תלמי השני","פיליפוס"]},{"text":"כמה נרות מדליקים בסך הכול בכל שמונת הלילות, כולל השמש?","options":["36","44","45","52"]},{"text":"בארץ ישראל כתוב על הסביבון נ־ג־ה־פ. מה כתוב עליו בחוץ לארץ?","options":["נ־ג־ה־ש","נ־ג־ש־פ","נ־ג־ה־מ","נ־ש־ה־פ"]},{"text":"לפי המסורת, אילו מאכלים נוהגים לאכול בחנוכה לזכר יהודית?","options":["מאכלי חלב וגבינה","דגים","תפוחים בדבש","אורז ועדשים"]},{"text":"מה שמו של אבי החשמונאים, שפתח במרד במודיעין? (הקלידו)"}]}', 100, '{"method":"per_item","points":60}', 1, 'captain_only', '{"sequential":true}', 'candidate', true),
('demo-pictures', 13, 'three_pictures', 'שלוש התמונות', 'בכל מקצה שלוש תמונות כמעט זהות. כל הבדל מופיע רק באחת מהן. מצאו את התמונה שיש בה הכי הרבה הבדלים משתי האחרות.', '{"heats":[{"title":"הסלון בערב חנוכה","pictures":[{"type":"room","wide":true,"kippah":"red","donuts":4,"window":"closed","candles":4,"shamash":true,"dreidel":"נ","cat":true,"frame":"gold","moon":true},{"type":"room","wide":true,"kippah":"blue","donuts":3,"window":"open","candles":4,"shamash":true,"dreidel":"נ","cat":false,"frame":"gold","moon":true},{"type":"room","wide":true,"kippah":"red","donuts":3,"window":"closed","candles":3,"shamash":true,"dreidel":"נ","cat":true,"frame":"gold","moon":true}]},{"title":"מטבח הסופגניות","pictures":[{"type":"kitchen","apron":"green","hat":true,"tray":6,"jam":"red","clock":9,"steam":true,"bowl":"blue"},{"type":"kitchen","apron":"red","hat":true,"tray":5,"jam":"red","clock":3,"steam":false,"bowl":"blue"},{"type":"kitchen","apron":"red","hat":false,"tray":5,"jam":"red","clock":3,"steam":true,"bowl":"yellow"}]},{"title":"רחוב בלילה","pictures":[{"type":"street","wcandles":5,"door":"blue","lamp":false,"tree":true,"dreidel":"teal","moon":"full","bike":false},{"type":"street","wcandles":5,"door":"blue","lamp":true,"tree":false,"dreidel":"teal","moon":"crescent","bike":false},{"type":"street","wcandles":6,"door":"red","lamp":true,"tree":true,"dreidel":"orange","moon":"crescent","bike":false}]}],"choices":["א","ב","ג"]}', 150, '{"method":"per_item","points":100}', 1, 'captain_only', '{}', 'candidate', true),
('demo-vault', 4, 'code_vault', 'הכספת החשמונאית', 'ארבע חידות, ובכל אחת מסתתרת ספרה. כל חידה מסומנת באות מהסביבון. רמז הסדר יגלה לכם באיזה סדר להקליד את הקוד. יש 3 ניסיונות.', '{"clues":[{"label":"ה","text":"כמה נרות מדליקים בסך הכול בלילות השני, השלישי והרביעי, בלי השמש?"},{"label":"פ","text":"כמה בנים היו למתתיהו החשמונאי?"},{"label":"נ","text":"באחד הלילות דולקים בחנוכייה, יחד עם השמש, נרות כמספר בני מתתיהו ועוד שניים. איזה לילה זה?"},{"label":"ג","text":"בכמה מתוך שמונת הלילות דולק בחנוכייה מספר זוגי של נרות, בלי לספור את השמש?"}],"order_clue":"הקלידו את הספרות לפי הסדר שבו הסביבון מספר את הנס."}', 240, '{"method":"fixed","points":300}', 3, 'captain_only', '{"instant_feedback":true}', 'candidate', true),
('demo-memory', 35, 'sequence_memory', 'זיכרון הנרות', 'נציג אחד מכל קבוצה. צופים ברצף ומשחזרים אותו. בכל שלב הרצף מתארך, וטעות אחת מסיימת את הריצה.', '{"symbols":["oil","dreidel","candle","sufganiya","menorah","coin","jar"],"show_ms_per_symbol":900,"stages":[["oil","dreidel","candle"],["jar","coin","menorah","oil"],["candle","sufganiya","dreidel","coin","jar"],["menorah","oil","jar","candle","coin","dreidel"],["coin","candle","oil","sufganiya","jar","dreidel","menorah"],["dreidel","jar","menorah","coin","oil","candle","sufganiya","jar"]]}', 300, '{"method":"per_stage","points":50}', 1, 'captain_only', '{"sequential":true,"eliminate_on_fail":true,"instant_feedback":true}', 'candidate', true),
('demo-truth', 8, 'truth_or_fiction', 'האמת או ההמצאה?', 'בכל סט ארבע עובדות: שלוש אמיתיות ואחת מומצאת. מצאו את המומצאת.', '{"items":[{"facts":["בחנוכה אומרים הלל שלם בכל שמונת ימי החג.","סיפור נס פך השמן מופיע בתלמוד הבבלי, במסכת שבת.","ספרי המקבים נכללים בתנ\"ך העברי, בחלק הכתובים.","חנוכה הוא החג היחיד בלוח העברי שנמשך על פני שני חודשים: כסלו וטבת."]},{"facts":["המשחק בסביבון בחנוכה מוזכר במפורש בתלמוד.","ביידיש הסביבון נקרא \"דריידל\".","על סביבונים בארץ ישראל מופיעה האות פ׳: \"נס גדול היה פה\".","הלביבות המסורתיות של יהודי מזרח אירופה עשויות בעיקר מתפוחי אדמה."]},{"facts":["בית המקדש נחנך מחדש בכ\"ה בכסלו.","יהודה המכבי היה אחד מבניו של מתתיהו.","לפי אחד ההסברים, הכינוי \"מכבי\" בא מהמילה \"מקבת\", שפירושה פטיש.","יהודה המכבי נהרג בקרב על חומות ירושלים, ביום חנוכת המקדש."]}]}', 150, '{"method":"per_item","points":100}', 1, 'captain_only', '{}', 'candidate', true),
('demo-order', 17, 'ordering', 'הסדר הנכון', 'סדרו את האירועים לפי סדר הזמנים, מהמוקדם (למעלה) למאוחר (למטה). יש ניקוד חלקי על כל זוג שסידרתם נכון.', '{"items":[{"id":"e","label":"טיהור המקדש וחנוכת המזבח"},{"id":"b","label":"מתתיהו פותח במרד במודיעין"},{"id":"f","label":"יהודה המכבי נופל בקרב"},{"id":"a","label":"אנטיוכוס גוזר גזירות על היהודים"},{"id":"d","label":"המכבים משחררים את ירושלים"},{"id":"c","label":"מתתיהו מת, ויהודה עומד בראש המורדים"}]}', 120, '{"method":"partial","points":300}', 1, 'captain_only', '{}', 'candidate', true),
('demo-slide', 26, 'sliding_puzzle', 'פאזל ההחלקה', 'נציג אחד מכל קבוצה. מזיזים אריחים אל המשבצת הריקה עד שהתמונה מסודרת. מי שמסיים מהר יותר מקבל יותר נקודות.', '{"start":[7,3,6,2,0,8,1,4,5],"scene":{"type":"room","kippah":"blue","donuts":4,"window":"open","candles":8,"shamash":true,"dreidel":"נ","cat":true,"frame":"gold","moon":true}}', 240, '{"method":"time_linear","points":300,"minRatio":0.3}', 1, 'captain_only', '{}', 'candidate', true),
('demo-bet', 31, 'bet_puzzle', 'הימור בחידה', 'קודם בוחרים מסלול הימור, ורק אחר כך נחשפת החידה: מי בחר באיזו חנוכייה?', '{"people":["סבתא רחל","דוד אבי","נועה","איתי"],"items":["חנוכיית כסף","חנוכיית זכוכית לשמן","חנוכיית לגו","חנוכיית חימר"],"clues":["דוד אבי בחר בחנוכייה שאינה עשויה ממתכת, וגם לא מזכוכית.","נועה ואיתי לא בחרו בחנוכיית הכסף.","חנוכיית הלגו לא שייכת לדוד אבי.","נועה לא מדליקה בשמן, ולכן לא בחרה בחנוכיית הזכוכית."]}', 240, '{"method":"bet"}', 1, 'captain_only', '{"bet":{"baseMethod":"average_floor100","minBase":100,"defaultTrack":"safe","tracks":[{"id":"safe","label":"זהיר","winMultiplier":0.5,"lossMultiplier":0},{"id":"mid","label":"נועז","winMultiplier":1,"lossMultiplier":0.5},{"id":"all","label":"הכול או כלום","winMultiplier":2,"lossMultiplier":1}]}}', 'candidate', true),
('demo-finale', null, 'finale', 'הַשַּׁמָּשׁ', 'חידת הגמר (לדוגמה). רק שתי הקבוצות הראשונות שפותרות מקבלות נקודות.', '{"answer_type":"code","puzzle":"קחו את מספר הלילה שבו דולקים לראשונה יותר נרות (בלי השמש) ממספר בני מתתיהו. כפלו אותו במספר האותיות שעל הסביבון, והוסיפו את התאריך בכסלו שבו מדליקים את הנר הראשון. מה יצא?"}', 300, '{"method":"finals"}', 5, 'captain_only', '{"instant_feedback":true}', 'candidate', true),
('demo-video', 5, 'video_memory', '[דמה] מה ראיתם עכשיו?', 'צפו בסרטון וענו על השאלות.', '{"video":null,"questions":[{"text":"[שאלת דמה]","options":["א","ב","ג","ד"]}]}', 90, '{"method":"per_item","points":100}', 1, 'captain_only', '{}', 'backup', true),
('demo-symbols', 11, 'symbols', 'חנוכה בסמלים', 'חמש חידות, בכל סדר. הקלידו את התשובה.', '{"puzzles":[{"symbols":["oil","jar"]},{"symbols":["miracle","temple"]}]}', 180, '{"method":"per_item","points":60}', 3, 'captain_only', '{"instant_feedback":true}', 'backup', true)
